BEGIN TRANSACTION;
CREATE TABLE activity_log (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id    INTEGER NULL,
  student_id INTEGER NULL,
  action     TEXT NOT NULL,
  ip         TEXT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE custom_documents (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id  INTEGER NOT NULL,
  title       TEXT NOT NULL,
  file_path   TEXT NOT NULL,
  file_name   TEXT NOT NULL,
  file_size   INTEGER NULL,
  mime_type   TEXT NULL,
  created_at  DATETIME NOT NULL,
  created_by  INTEGER NULL
);
CREATE TABLE login_attempts (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  ip         TEXT NOT NULL,
  username   TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE student_documents (
  student_id  INTEGER NOT NULL,
  doc_index   INTEGER NOT NULL,
  status      TEXT NOT NULL,
  updated_by  INTEGER NULL,
  updated_at  TEXT NOT NULL, file_path TEXT NULL, file_name TEXT NULL, file_size INTEGER NULL, mime_type TEXT NULL, uploaded_at TEXT NULL, uploaded_by INTEGER NULL,
  PRIMARY KEY (student_id, doc_index),
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
CREATE TABLE students (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  name              TEXT NOT NULL,
  counselor         TEXT NULL,
  officer_id        INTEGER NULL,
  entered_by        INTEGER NULL,
  refund            TEXT NULL,
  branch            TEXT NULL,
  intake            TEXT NULL,
  received_date     TEXT NULL,
  consult1          TEXT NULL,
  consent           TEXT NULL,
  docs_checklist    TEXT NULL,
  initial_meeting   TEXT NULL,
  follow_up_1       TEXT NULL,
  recorded_uploaded TEXT NULL,
  drive_link        TEXT NULL,
  meeting_priority  TEXT NULL,
  second_meeting    TEXT NULL,
  follow_up_2       TEXT NULL,
  tax_meeting       TEXT NULL,
  follow_up_3       TEXT NULL,
  offer             TEXT NULL,
  consult2          TEXT NULL,
  disc2             TEXT NULL,
  enrollment        TEXT NULL,
  consult3          TEXT NULL,
  disc3             TEXT NULL,
  visa              TEXT NULL,
  last_installment  TEXT NULL,
  remarks           TEXT NULL,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NULL
, csc_status TEXT DEFAULT NULL, csc_verified_at TEXT DEFAULT NULL, csc_verified_by INTEGER DEFAULT NULL, sheet_sr INTEGER, email TEXT, student_password TEXT, portal_id TEXT, portal_password TEXT, shortlisting TEXT, pending_docs_note TEXT, doc_request_date TEXT, enrollment_date TEXT, installment_1 TEXT, installment_2 TEXT, installment_3 TEXT, installment_4 TEXT, threat_cancellation TEXT, meeting_link TEXT, drive_files_json TEXT NULL, frontend_officer_id INTEGER DEFAULT NULL, frontend_officer_name TEXT DEFAULT NULL);
CREATE TABLE users (
  id                   INTEGER PRIMARY KEY AUTOINCREMENT,
  name                 TEXT NOT NULL,
  username             TEXT NOT NULL UNIQUE,
  password_hash        TEXT NOT NULL,
  role                 TEXT NOT NULL CHECK(role IN ('admin','officer','student')),
  student_id           INTEGER NULL UNIQUE,
  active               INTEGER NOT NULL DEFAULT 1,
  must_change_password INTEGER NOT NULL DEFAULT 1,
  last_login           TEXT NULL,
  created_at           TEXT NOT NULL, department TEXT DEFAULT 'backend',
  FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
);
DELETE FROM "sqlite_sequence";
CREATE TABLE IF NOT EXISTS correction_requests (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id        INTEGER NOT NULL,
  requested_by      INTEGER NOT NULL,
  requested_by_name TEXT NOT NULL,
  field_name        TEXT NOT NULL,
  old_value         TEXT NULL,
  new_value         TEXT NOT NULL,
  reason            TEXT NOT NULL,
  status            TEXT NOT NULL DEFAULT 'pending',
  reviewed_by       INTEGER NULL,
  reviewed_by_name  TEXT NULL,
  reviewed_at       TEXT NULL,
  reviewer_notes    TEXT NULL,
  created_at        TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS api_tokens (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id           INTEGER NOT NULL,
  token             TEXT NOT NULL UNIQUE,
  role              TEXT NOT NULL,
  created_at        TEXT NOT NULL,
  expires_at        TEXT NOT NULL
);
COMMIT;
